    skills: { basic: { name: '大郎汤药', icon: 'skill_100801_1', descriptions: ['甩出1道汤药，每攻击7次，为2名英雄分别进行大幅治疗和小幅治疗。', '攻速+15%', '全部英雄攻击和生命+10%', '攻速+35%'] }, ultimate: { name: '觉醒:神奇汤药', icon: 'skill_100801_2', descriptions: ['泼出4道可穿透3次的神奇汤药。', '增加到5道可无限穿透的神奇汤药。'] } },
