    starProgression: [{ starTier: 1, levelCap: 5, base: { attack: 50, hp: 500 }, max: { attack: 110, hp: 1100 }, raw: { BasicAttributes1: 50, AttackBase: 15, BasicAttributes2: 500, HpBase: 150 } }, { starTier: 2, levelCap: 10, base: { attack: 100, hp: 1000 }, max: { attack: 280, hp: 2800 }, raw: { BasicAttributes1: 100, AttackBase: 20, BasicAttributes2: 1000, HpBase: 200 } }, { starTier: 3, levelCap: 15, base: { attack: 150, hp: 1500 }, max: { attack: 500, hp: 5000 }, raw: { BasicAttributes1: 150, AttackBase: 25, BasicAttributes2: 1500, HpBase: 250 } }, { starTier: 4, levelCap: 25, base: { attack: 250, hp: 2500 }, max: { attack: 1330, hp: 13300 }, raw: { BasicAttributes1: 250, AttackBase: 45, BasicAttributes2: 2500, HpBase: 450 } }, { starTier: 5, levelCap: 30, base: { attack: 300, hp: 3000 }, max: { attack: 1750, hp: 17500 }, raw: { BasicAttributes1: 300, AttackBase: 50, BasicAttributes2: 3000, HpBase: 500 } }, { starTier: 6, levelCap: 35, base: { attack: 350, hp: 3500 }, max: { attack: 2220, hp: 22200 }, raw: { BasicAttributes1: 350, AttackBase: 55, BasicAttributes2: 3500, HpBase: 550 } }, { starTier: 7, levelCap: 40, base: { attack: 500, hp: 5000 }, max: { attack: 2840, hp: 28400 }, raw: { BasicAttributes1: 500, AttackBase: 60, BasicAttributes2: 5000, HpBase: 600 } }, { starTier: 8, levelCap: 45, base: { attack: 600, hp: 6000 }, max: { attack: 3460, hp: 34600 }, raw: { BasicAttributes1: 600, AttackBase: 65, BasicAttributes2: 6000, HpBase: 650 } }, { starTier: 9, levelCap: 50, base: { attack: 700, hp: 7000 }, max: { attack: 4130, hp: 41300 }, raw: { BasicAttributes1: 700, AttackBase: 70, BasicAttributes2: 7000, HpBase: 700 } }, { starTier: 10, levelCap: 55, base: { attack: 800, hp: 8000 }, max: { attack: 4850, hp: 48500 }, raw: { BasicAttributes1: 800, AttackBase: 75, BasicAttributes2: 8000, HpBase: 750 } }, { starTier: 11, levelCap: 60, base: { attack: 875, hp: 8750 }, max: { attack: 5595, hp: 55950 }, raw: { BasicAttributes1: 875, AttackBase: 80, BasicAttributes2: 8750, HpBase: 800 } }, { starTier: 12, levelCap: 65, base: { attack: 1000, hp: 10000 }, max: { attack: 6440, hp: 64400 }, raw: { BasicAttributes1: 1000, AttackBase: 85, BasicAttributes2: 10000, HpBase: 850 } }, { starTier: 13, levelCap: 70, base: { attack: 1125, hp: 11250 }, max: { attack: 7335, hp: 73350 }, raw: { BasicAttributes1: 1125, AttackBase: 90, BasicAttributes2: 11250, HpBase: 900 } }, { starTier: 14, levelCap: 75, base: { attack: 1250, hp: 12500 }, max: { attack: 8280, hp: 82800 }, raw: { BasicAttributes1: 1250, AttackBase: 95, BasicAttributes2: 12500, HpBase: 950 } }, { starTier: 15, levelCap: 80, base: { attack: 1375, hp: 13750 }, max: { attack: 9275, hp: 92750 }, raw: { BasicAttributes1: 1375, AttackBase: 100, BasicAttributes2: 13750, HpBase: 1000 } }],
